#include <stdio.h>
#include <string.h>

typedef enum { CLOSED, OPEN, HALF_OPEN } State;

static int failure_threshold;
static int reset_timeout;
static State state = CLOSED;
static int failures = 0;
static int opened_at = 0;

static void do_init(int threshold, int timeout) {
    failure_threshold = threshold;
    reset_timeout = timeout;
    state = CLOSED;
    failures = 0;
}

static void do_call(const char *outcome, int now) {
    if (state == OPEN) {
        if (now - opened_at < reset_timeout) {
            printf("blocked\n");
            return;
        }
        state = HALF_OPEN;
    }

    int ok = strcmp(outcome, "ok") == 0;
    printf("ran:%s\n", outcome);

    if (ok) {
        state = CLOSED;
        failures = 0;
    } else {
        if (state == HALF_OPEN) {
            state = OPEN;
            opened_at = now;
        } else {
            failures++;
            if (failures >= failure_threshold) {
                state = OPEN;
                opened_at = now;
            }
        }
    }
}

int main(void) {
    char cmd[16], outcome[8];
    int a, b;
    while (scanf("%15s", cmd) == 1) {
        if (strcmp(cmd, "init") == 0) {
            if (scanf("%d %d", &a, &b) == 2) do_init(a, b);
        } else if (strcmp(cmd, "call") == 0) {
            if (scanf("%7s %d", outcome, &a) == 2) do_call(outcome, a);
        }
    }
    return 0;
}

